# mzTab Export targets section.

targets_section_export_mztab <- function() {
  tar_target(
    name = exp_mzt,
    command = {
      .scalar_chr_or <- function(x, default = NULL) {
        if (is.null(x) || length(x) == 0L) {
          return(default)
        }
        if (is.character(x)) {
          x <- x[[1L]]
          if (is.na(x) || !nzchar(x) || identical(x, "null")) {
            return(default)
          }
          return(x)
        }
        x
      }
      .null_or <- function(x, default) {
        .scalar_chr_or(x, default = default)
      }
      .output_in_input_dir <- function(input_path, configured_output) {
        if (is.null(input_path) || !nzchar(input_path)) {
          return(configured_output)
        }
        out_name <- basename(configured_output)
        if (
          is.null(out_name) || !nzchar(out_name) || identical(out_name, "null")
        ) {
          out_name <- paste0(
            tools::file_path_sans_ext(basename(input_path)),
            ".mztab"
          )
        }
        file.path(dirname(input_path), out_name)
      }
      mzt_xrefs <- tryCatch(par_exp_mzt$files$xrefs, error = function(e) NULL)
      if (is.null(mzt_xrefs) || !nzchar(.null_or(mzt_xrefs, ""))) {
        mzt_xrefs <- lib_xrefs
      }
      mzt_contact <- tryCatch(par_exp_mzt$contact, error = function(e) NULL)
      if (
        !is.null(mzt_contact) &&
          all(vapply(
            mzt_contact,
            function(x) !nzchar(.null_or(x, "")),
            logical(1L)
          ))
      ) {
        mzt_contact <- NULL
      }
      base_mzt <- if (!is.null(par_exp_mzt$files$mztab$raw)) {
        raw_path <- par_exp_mzt$files$mztab$raw
        raw_path <- .scalar_chr_or(raw_path, default = NULL)
        if (!is.null(raw_path) && file.exists(raw_path)) {
          raw_path
        } else {
          NULL
        }
      } else {
        NULL
      }
      mzt_input <- .scalar_chr_or(ann_wei, default = ann_wei)
      mzt_output_cfg <- .scalar_chr_or(
        par_exp_mzt$files$output$mztab,
        default = par_exp_mzt$files$output$mztab
      )
      write_mztab(
        input = mzt_input,
        output = .output_in_input_dir(
          input_path = mzt_input,
          configured_output = mzt_output_cfg
        ),
        ms_run_location = .null_or(
          tryCatch(par_exp_mzt$ms$run_location, error = function(e) NULL),
          "null"
        ),
        ms_run_format = .null_or(
          tryCatch(par_exp_mzt$ms$run_format, error = function(e) NULL),
          "null"
        ),
        ms_run_id_format = .null_or(
          tryCatch(par_exp_mzt$ms$run_id_format, error = function(e) NULL),
          "null"
        ),
        polarity = tryCatch(par_exp_mzt$ms$polarity, error = function(e) NULL),
        instrument = .null_or(
          tryCatch(par_exp_mzt$ms$instrument, error = function(e) NULL),
          NULL
        ),
        title = .null_or(
          tryCatch(par_exp_mzt$study$title, error = function(e) NULL),
          "TIMA annotation results"
        ),
        description = .null_or(
          tryCatch(par_exp_mzt$study$description, error = function(e) NULL),
          paste0(
            "Annotation results produced by Taxonomically Informed ",
            "Metabolomics Annotation (TIMA)."
          )
        ),
        sample_name = .null_or(
          tryCatch(par_exp_mzt$study$sample_name, error = function(e) NULL),
          NULL
        ),
        publication = .null_or(
          tryCatch(par_exp_mzt$study$publication, error = function(e) NULL),
          NULL
        ),
        contact = mzt_contact,
        xrefs_file = mzt_xrefs,
        edges_file = .null_or(
          tryCatch(par_exp_mzt$files$edges, error = function(e) NULL),
          NULL
        ),
        base_mztab = base_mzt
      )
    },
    format = "file",
    garbage_collection = TRUE
  )
}

# Benchmark targets section.

targets_section_benchmark <- function() {
  list(
    tar_target(name = benchmark_path_mgf_neg, command = {
      paths$data$source$benchmark$mgf$neg
    }),
    tar_target(name = benchmark_path_mgf_pos, command = {
      paths$data$source$benchmark$mgf$pos
    }),
    tar_target(
      name = benchmark_file,
      command = {
        c(lib_spe_exp_gnp_pre_pos, lib_spe_exp_gnp_pre_neg)
      },
      format = "file"
    ),
    tar_target(
      name = benchmark_converted,
      command = {
        sp <- getFromNamespace("import_and_clean_library_collection", "tima")(
          benchmark_file,
          dalton = 0.01,
          polarity = NA,
          ppm = 10
        )
        getFromNamespace("export_spectra_rds", "tima")(
          Spectra::filterEmptySpectra(sp),
          file = "data/interim/benchmark/benchmark_spectra.rds"
        )
        return("data/interim/benchmark/benchmark_spectra.rds")
      },
      format = "file"
    ),
    tar_target(
      name = benchmark_prepared,
      command = {
        sp <- import_spectra(benchmark_converted, sanitize = FALSE)
        sp@backend@spectraData$precursorMz <- as.numeric(
          sp@backend@spectraData$precursor_mz
        )
        getFromNamespace("log_trace", "tima")("Imported")
        sp_clean <- sp
        getFromNamespace("log_trace", "tima")("Cleaned")
        df_meta <- tidytable::mutate(
          tidytable::tidytable(
            adduct = sp_clean$adduct,
            inchikey = sp_clean$inchikey,
            fragments = as.numeric(as.character(purrr::map(
              .x = sp_clean@backend@peaksData,
              .f = length
            ))) /
              2,
            precursorMz = sp_clean$precursorMz,
            smiles = sp_clean$smiles,
            ccmslib = sp_clean$spectrum_id,
            charge = sp_clean$precursorCharge,
            name = sp_clean$name
          ),
          tidytable::across(
            .cols = tidyselect::everything(),
            .fns = function(x) {
              tidytable::na_if(x, "")
            }
          )
        )
        getFromNamespace("log_trace", "tima")("Framed")
        df_clean <- tidytable::mutate(
          tidytable::mutate(
            tidytable::distinct(
              tidytable::mutate(
                tidytable::select(
                  tidytable::filter(
                    tidytable::filter(
                      tidytable::separate(
                        tidytable::mutate(
                          tidytable::select(
                            tidytable::filter(
                              tidytable::filter(
                                tidytable::filter(
                                  tidytable::filter(
                                    tidytable::filter(
                                      tidytable::filter(
                                        df_meta,
                                        !is.na(inchikey)
                                      ),
                                      fragments >= 5
                                    ),
                                    fragments <= 250
                                  ),
                                  !grepl(
                                    pattern = "ReSpect",
                                    x = name,
                                    fixed = TRUE
                                  )
                                ),
                                !grepl(
                                  pattern = "Spectral Match to",
                                  x = name,
                                  fixed = TRUE
                                )
                              ),
                              !grepl(
                                pattern = "putative",
                                x = name,
                                fixed = TRUE
                              )
                            ),
                            -name
                          ),
                          mass = precursorMz
                        ),
                        col = mass,
                        sep = "\\.",
                        into = c("a", "b")
                      ),
                      !is.na(b)
                    ),
                    stri_length(as.numeric(b)) > 1
                  ),
                  -a,
                  -b
                ),
                inchikey_connectivity_layer = gsub(
                  pattern = "-.*",
                  replacement = "",
                  x = inchikey,
                  perl = TRUE
                )
              ),
              inchikey_connectivity_layer,
              adduct,
              .keep_all = TRUE
            ),
            mz = precursorMz
          ),
          rt = tidytable::cur_group_id(),
          .by = "inchikey_connectivity_layer"
        )
        df_clean_neg <- tidytable::filter(
          df_clean,
          grepl(pattern = "]-", x = adduct, fixed = TRUE)
        )
        df_clean_pos <- tidytable::filter(
          df_clean,
          grepl(pattern = "]+", x = adduct, fixed = TRUE)
        )
        sp_pos <- sp_clean[sp_clean$spectrum_id %in% df_clean_pos$ccmslib]
        sp_neg <- sp_clean[sp_clean$spectrum_id %in% df_clean_neg$ccmslib]
        extract_benchmark_spectra <- function(x, mode) {
          df <- data.frame(tidytable::select(
            tidytable::mutate(
              tidytable::mutate(
                tidytable::mutate(
                  tidytable::mutate(
                    tidytable::mutate(
                      tidytable::mutate(
                        getFromNamespace("extract_spectra", "tima")(x),
                        acquisitionNum = tidytable::row_number()
                      ),
                      spectrum_id = acquisitionNum
                    ),
                    short_ik = gsub(
                      pattern = "-.*",
                      replacement = "",
                      inchikey,
                      perl = TRUE
                    )
                  ),
                  rtime = tidytable::cur_group_id(),
                  .by = "short_ik"
                ),
                precursorCharge = tidytable::if_else(
                  condition = mode == "pos",
                  true = as.integer(1),
                  false = as.integer(-1)
                )
              ),
              MS_LEVEL = 2L
            ),
            acquisitionNum,
            precursorCharge,
            precursorMz,
            MS_LEVEL,
            rtime,
            name = name,
            smiles = smiles,
            inchi = inchi,
            inchikey = inchikey,
            adduct = adduct,
            ccmslib = spectrum_id,
            spectrum_id = acquisitionNum,
            mz,
            intensity
          ))
          df
        }
        spectra_harmonized_pos <- extract_benchmark_spectra(
          sp_pos,
          mode = "pos"
        )
        spectra_harmonized_neg <- extract_benchmark_spectra(
          sp_neg,
          mode = "neg"
        )
        select_benchmark_columns <- function(x) {
          df <- data.frame(tidytable::mutate(
            tidytable::select(
              x,
              adduct,
              inchikey,
              smiles,
              ccmslib,
              charge = precursorCharge,
              mz = precursorMz,
              rt = rtime,
              feature_id = spectrum_id
            ),
            inchikey_connectivity_layer = gsub(
              pattern = "-.*",
              replacement = "",
              x = inchikey,
              perl = TRUE
            )
          ))
          df
        }
        df_clean_pos <- select_benchmark_columns(spectra_harmonized_pos)
        df_clean_neg <- select_benchmark_columns(spectra_harmonized_neg)
        Spectra::export(
          Spectra::Spectra(spectra_harmonized_pos),
          backend = MsBackendMgf::MsBackendMgf(),
          file = benchmark_path_mgf_pos
        )
        Spectra::export(
          Spectra::Spectra(spectra_harmonized_neg),
          backend = MsBackendMgf::MsBackendMgf(),
          file = benchmark_path_mgf_neg
        )
        getFromNamespace("export_output", "tima")(
          df_clean_pos,
          "data/interim/benchmark/benchmark_meta_pos.tsv"
        )
        getFromNamespace("export_output", "tima")(
          df_clean_neg,
          "data/interim/benchmark/benchmark_meta_neg.tsv"
        )
        return(c(
          spectra_pos = benchmark_path_mgf_pos,
          spectra_neg = benchmark_path_mgf_neg,
          meta_pos = "data/interim/benchmark/benchmark_meta_pos.tsv",
